import hashlib
import hmac
import os
import time
import threading
import json
from collections import OrderedDict

SECRET_KEY = os.environ.get('SESSION_SECRET', 'fallback-dev-key-do-not-use').encode()

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._sessions = {}
        self._revoked = set()

    def create_session(self, user_id, role='user', permissions=None):
        """Create a new session with given attributes."""
        if permissions is None:
            permissions = {'read': True, 'write': False, 'admin': False}

        session_id = os.urandom(16).hex()
        session_data = {
            'user_id': user_id,
            'role': role,
            'permissions': permissions,
            'created_at': time.time(),
            'upgraded': False
        }

        with self._lock:
            self._sessions[session_id] = session_data

        token = self._sign_session(session_id, session_data)
        return session_id, token

    def _sign_session(self, session_id, data):
        """Create HMAC-signed token for session."""
        payload = json.dumps({'sid': session_id, 'uid': data['user_id'],
                             'role': data['role'], 'ts': data['created_at']},
                            sort_keys=True)
        mac = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}|{mac}"

    def verify_token(self, token):
        """Verify token signature and return session_id."""
        try:
            payload, mac = token.rsplit('|', 1)
            expected = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
            if not hmac.compare_digest(mac, expected):
                return None
            data = json.loads(payload)
            return data.get('sid')
        except (ValueError, json.JSONDecodeError):
            return None

    def revoke_session(self, session_id):
        """Revoke a session."""
        with self._lock:
            self._revoked.add(session_id)
            if session_id in self._sessions:
                del self._sessions[session_id]

    def is_revoked(self, session_id):
        """Check if session is revoked."""
        with self._lock:
            return session_id in self._revoked

    def get_session(self, session_id):
        """Get session data."""
        with self._lock:
            return self._sessions.get(session_id, {}).copy()

    def upgrade_session(self, session_id, requesting_user_id):
        """Upgrade a session to admin privileges.
        Only the session owner can request an upgrade.
        Returns True if upgrade was successful."""
        with self._lock:
            session = self._sessions.get(session_id)
            if session is None:
                return False
            if session['user_id'] != requesting_user_id:
                return False
            if session['upgraded']:
                return False  # Already upgraded, prevent double-upgrade
            session['upgraded'] = True

        # Perform async verification (simulates external auth service call)
        # This happens outside the lock to avoid blocking
        verified = self._verify_upgrade_eligibility(requesting_user_id)

        if verified:
            with self._lock:
                session = self._sessions.get(session_id)
                if session is not None:
                    session['permissions'] = {'read': True, 'write': True, 'admin': True}
                    session['role'] = 'admin'
            return True
        else:
            # Rollback the upgrade flag
            with self._lock:
                session = self._sessions.get(session_id)
                if session is not None:
                    session['upgraded'] = False
            return False

    def _verify_upgrade_eligibility(self, user_id):
        """Simulate external verification. In production this calls an auth service."""
        # Simulate network delay
        time.sleep(0.01)
        # For this example, users with even IDs are eligible
        return user_id % 2 == 0


def check_access(store, token, required_permission):
    """Check if a token grants the required permission.

    Security flow:
    1. Verify token signature (HMAC)
    2. Check session not revoked
    3. Check permission in session data
    """
    session_id = store.verify_token(token)
    if session_id is None:
        return False

    # Check revocation
    if store.is_revoked(session_id):
        return False

    # Get current session permissions
    session = store.get_session(session_id)
    if not session:
        return False

    permissions = session.get('permissions', {})
    return permissions.get(required_permission, False)


def handle_admin_action(store, token, action_data):
    """Handle an admin action request.

    Validates the token has admin permission before executing.
    """
    if not check_access(store, token, 'admin'):
        return {'error': 'Access denied', 'status': 403}

    # Execute admin action
    return {'result': f'Executed: {action_data}', 'status': 200}


def handle_upgrade_request(store, token):
    """Handle a session upgrade request.

    The user presents their token to request admin privileges.
    """
    session_id = store.verify_token(token)
    if session_id is None:
        return {'error': 'Invalid token', 'status': 401}

    if store.is_revoked(session_id):
        return {'error': 'Session revoked', 'status': 401}

    session = store.get_session(session_id)
    if not session:
        return {'error': 'Session not found', 'status': 404}

    user_id = session['user_id']
    success = store.upgrade_session(session_id, user_id)

    if success:
        return {'result': 'Session upgraded to admin', 'status': 200}
    else:
        return {'error': 'Upgrade denied', 'status': 403}
